{
  "PROP-6a4369e9-inv-025": {
    "property_id": "PROP-6a4369e9-inv-025",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-025",
      "classification": "potential-vulnerability",
      "code_path": "beacon-chain/sync/rpc_data_column_sidecars_by_root.go::dataColumnSidecarByRootRPCHandler::L123",
      "proof_trace": "Storage contains data columns verified via RPC by_root (ByRootRequestDataColumnSidecarRequirements: 3 checks) mixed with gossip-validated columns (GossipDataColumnSidecarRequirements: 12 checks). RPC by_root handler serves from storage without re-validating gossip requirements, potentially serving columns for blocks that fail proposer signature, parent validity, or finality checks.",
      "attack_scenario": "Attacker provides data column via RPC with valid KZG/inclusion proofs but invalid proposer signature. Node saves to storage, later serves it to peers via by_root RPC, violating the invariant that served sidecars must pass full gossip validation.",
      "checklist_id": "PROP-6a4369e9-inv-025"
    },
    "text": "Sidecars must not be served for blocks failing gossip validation in by_root responses.",
    "assertion": "forall sidecar in resp: gossip_valid(sidecar.block) == true",
    "covers": "SG-009",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

